  const r = await api(ED.id + "/ai", "POST", { instruction: text, selected: ED.sel != null ? { page: ED.page, i: ED.sel } : null }); $("#wb-cf button").disabled = false;
  if (!r.ok) { $("#wb-cs").textContent = r.reason; return; }
